import java.util.List;
import java.util.Scanner;
import java.util.function.Predicate;

public class Main {
    // 条件を受け取って、当てはまる個数を返す
    static int count(List<Integer> list, Predicate<Integer> p) {
        int c = 0;
        for (int n : list) {
            if (p.test(n)) {
                c++;
            }
        }
        return c;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int k = sc.nextInt();

        List<Integer> numbers = new ArrayList<>();
        for (int i = 0; i < k; i++) {
            numbers.add(sc.nextInt());
        }

        Predicate<Integer> isEven = n -> n % 2 == 0;
        Predicate<Integer> isPositive = n -> n > 0;

        System.out.println("偶数 " + count(numbers, isEven));
        System.out.println("正 " + count(numbers, isPositive));
        System.out.println("偶数かつ正 " + count(numbers, isEven.and(isPositive)));
        System.out.println("偶数または正 " + count(numbers, isEven.or(isPositive)));
        System.out.println("奇数 " + count(numbers, isEven.negate()));

        numbers.removeIf(isEven.and(isPositive));
        System.out.println(numbers);

        try {
            List.of(1, 2).removeIf(n -> true);
        } catch (UnsupportedOperationException e) {
            System.out.println("不変 NG");
        }
    }
}

