import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int k = sc.nextInt();

        List<String> words = new ArrayList<>();
        for (int i = 0; i < k; i++) {
            words.add(sc.next());
        }

        List<String> longFirst = new ArrayList<>(words);
        longFirst.sort(Comparator.comparingInt(String::length).reversed());
        System.out.println("長い順 " + longFirst);

        List<String> longThenDict = new ArrayList<>(words);
        longThenDict.sort(Comparator.comparingInt(String::length).reversed()
                .thenComparing(Comparator.naturalOrder()));
        System.out.println("長い順→辞書順 " + longThenDict);

        List<String> byNull = new ArrayList<>(words);
        byNull.sort(null);
        System.out.println("null " + byNull);

        System.out.println("元 " + words);

        words.sort(Comparator.reverseOrder());
        System.out.println("破壊的 " + words);

        try {
            List.of("b", "a").sort(Comparator.naturalOrder());
        } catch (UnsupportedOperationException e) {
            System.out.println("不変 NG");
        }
    }
}
